import{_ as t}from"./chunks/editor-zeichnung.C5iY_LPV.js";import{_ as s,o as i,c as n,a3 as a}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse(`{"title":"HA Grafik Visual Studio","description":"Un tableau de bord (dashboard) pour Home Assistant qui sort de l'ordinaire : état actuel du développement et utilisation.","frontmatter":{"title":"HA Grafik Visual Studio","description":"Un tableau de bord (dashboard) pour Home Assistant qui sort de l'ordinaire : état actuel du développement et utilisation."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/index.md","filePath":"fr/projects/grafik-visual-studio/index.md","lastUpdated":1793198184000}`),r={name:"fr/projects/grafik-visual-studio/index.md"};function o(l,e,u,d,c,p){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="ha-grafik-visual-studio" tabindex="-1">HA Grafik Visual Studio <a class="header-anchor" href="#ha-grafik-visual-studio" aria-label="Permalink to &quot;HA Grafik Visual Studio {#ha-grafik-visual-studio}&quot;">​</a></h1><p><strong>Studio 0.1.296 :</strong> Les <strong>62 autres types de widgets</strong> bénéficient désormais de propriétés multilingues (DE/EN/FR), de messages d&#39;exécution, d&#39;une fonction optionnelle de contrôle de la climatisation (Climate), ainsi que d&#39;une vérification des sources, attributs et unités. Les projets et versions de paquets existants restent valides ; les nouveaux groupes sont créés à l&#39;état désactivé. <a href="/fr/projects/grafik-visual-studio/ha-quellen-climate">Guide et limitations</a>. Le fonctionnement avec des appareils réels ou via l&#39;application Companion n&#39;a pas encore été confirmé par des tests en conditions réelles. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/remaining-widget-audit-2026-10-12.md" target="_blank" rel="noreferrer">Rapport de test</a>.</p><p>À partir de la version <strong>0.1.289</strong>, l&#39;indicateur <strong>Enregistrer</strong> change brièvement de couleur lors de l&#39;opération : <strong>orange</strong> pendant le traitement de la requête, <strong>vert</strong> en cas de succès et <strong>rouge</strong> en cas d&#39;erreur. La couleur normale est rétablie après 1,4 seconde. Ce comportement s&#39;applique également à la sauvegarde automatique et fonctionne aussi bien en mode clair qu&#39;en mode sombre.</p><p>Depuis <strong>Studio 0.1.287</strong>, tous les widgets disposent, dans l&#39;onglet <strong>WIDGET</strong> (en haut), d&#39;une case à cocher intitulée <strong>Masquer à l&#39;exécution</strong> (<em>In Runtime verstecken</em>). Cette option permet de masquer le widget lors de l&#39;exécution, indépendamment de son indice Z (<em>Z-index</em>) ; il reste toutefois modifiable dans l&#39;éditeur. Les calculs et le flux de données demeurent actifs, même lorsque des widgets de type « Number » ou des « MathBox » sont masqués. Pensez à enregistrer le projet après avoir effectué cette modification.</p><p>Autres nouveautés depuis <strong>Studio 0.1.285</strong> : les éléments <a href="/fr/projects/grafik-visual-studio/svg-line">SVG-Line</a> et les connexions de valeurs bénéficient désormais de positions de départ verticales, d&#39;un tracé à angles droits (perpendiculaires) et d&#39;une manipulation des points moins sensible. Les sorties des potentiomètres (<a href="/fr/projects/grafik-visual-studio/industrial">Poti-Ausgänge</a>) contrôlent directement l&#39;animation des lignes. L&#39;exemple <a href="/fr/projects/grafik-visual-studio/svg-linebox-math">Number→Math</a> illustre le flux net de la batterie (voir <code>O - P</code>) ; la <a href="/fr/projects/grafik-visual-studio/bildergalerie">galerie</a> présente une image de l&#39;éditeur avant la démonstration animée.</p><p>Nouveauté dans Studio <strong>0.1.280</strong> : le composant <a href="/fr/projects/grafik-visual-studio/solar">Solar 0.1.3</a> propose sept points de connexion sur le bord inférieur de l&#39;onduleur. Il intègre également quatre entrées pour panneaux solaires sur la partie supérieure (tête de pile), des connexions pour batterie au niveau de la jointure du boîtier, des couleurs distinctes pour les valeurs liées à la batterie, ainsi qu&#39;un panneau solaire avec support, pouvant être inversé (effet miroir).</p><p>Nouveauté dans Studio <strong>0.1.215</strong> : Le <a href="/fr/projects/grafik-visual-studio/materialdesign">kit Material Design externe 1.0.0</a> comprend <strong>49 éléments (widgets)</strong>, incluant des fonctions d&#39;autocomplétion, des champs de saisie, des boutons, des affichages, des listes, des graphiques, des calendriers et des mises en page. Un projet comparatif permet de tester chaque widget individuellement.</p><p>Nouveauté dans Studio <strong>0.1.214</strong> : Le pack Material Design <strong>0.3.0</strong> intègre un <a href="/fr/projects/grafik-visual-studio/materialdesign">dialogue iFrame</a> — le troisième widget de la série — doté d&#39;une source, d&#39;un environnement isolé (sandbox), d&#39;options de défilement et de mises en page de dialogue compactes ou étendues.</p><p>Nouveauté dans Studio <strong>0.1.210</strong> : Le <a href="/fr/projects/grafik-visual-studio/materialdesign">kit Material Design externe</a> est lancé avec des <strong>aperçus de schémas de couleurs</strong> (Preview Color Schemes), proposant 26 gammes de couleurs ainsi que des styles « Classique », « Material 3 » et « Standard du projet ». Le pack 0.1.0 est prêt pour le test d&#39;enregistrement dans le catalogue de la communauté.</p><h2 id="paketkatalog-und-downloads" tabindex="-1">Catalogue de packs et téléchargements <a class="header-anchor" href="#paketkatalog-und-downloads" aria-label="Permalink to &quot;Catalogue de packs et téléchargements {#paketkatalog-und-downloads}&quot;">​</a></h2><p>Le pack <strong>Météo et Chauffage (Wetter und Heizung) 1.7.1</strong> affiche, pour sept widgets, les images d&#39;aperçu originales issues de <a href="https://github.com/rg-engineering/ioBroker.vis-2-widgets-weather-and-heating" target="_blank" rel="noreferrer">ioBroker weather-and-heating</a>. L&#39;élément « Informer mon propriétaire » (« Meinen Vermieter informieren ») est désormais accompagné d&#39;une icône en forme de lettre, car le fichier image référencé dans l&#39;original est manquant. La licence MIT relative aux images originales est incluse dans le pack. Cette mise à jour concerne uniquement les images des widgets ; les paramètres existants restent inchangés. L&#39;utilisation de Studio <strong>0.1.216</strong> (ou une version ultérieure) est requise pour effectuer cette mise à jour des images.</p><p>À partir de la page web du catalogue <strong>0.1.11</strong>, le paquet original téléversé lors de l&#39;enregistrement est conservé de manière privée pour être examiné par l&#39;administration. L&#39;analyse et la validation s&#39;appuient sur ce fichier sans nécessiter un nouveau téléversement ; toutefois, un nouveau fichier peut être téléversé en remplacement, si besoin. L&#39;administration a la possibilité de télécharger l&#39;original. L&#39;empreinte SHA-256 permet de détecter toute modification. Cette copie privée est supprimée une fois le paquet validé, rejeté, supprimé ou après l&#39;expiration de la période de conservation de 90 jours. Pour les soumissions plus anciennes, un nouveau téléversement unique est requis, car les versions précédentes se limitaient à l&#39;analyse du fichier.</p><p>À partir de la page web du catalogue <strong>0.1.10</strong>, l&#39;enregistrement de widgets accepte exclusivement le format <code>.wg</code>, tandis que l&#39;enregistrement d&#39;outils accepte exclusivement le format <code>.tp</code>. Le sélecteur de fichiers n&#39;affiche que l&#39;extension appropriée. Le serveur vérifie l&#39;extension des noms de fichiers téléversés et des chemins des liens de téléchargement, ainsi que le contenu du paquet et le type de manifeste. Cette vérification lors du téléversement s&#39;applique également aux opérations effectuées par l&#39;administration.</p><p>Sur la page web du catalogue <strong>0.1.9</strong>, le formulaire d&#39;enregistrement interroge sur l&#39;utilisation de nouvelles fonctionnalités Studio (Oui/Non/Incertain). En cas de réponse « Oui » ou « Incertain », une description est requise et la version minimale peut être indiquée comme « Encore inconnue ». En cas de réponse « Non », la précision d&#39;une version minimale est obligatoire. L&#39;administration définit la version minimale lors de l&#39;examen ou à la suite d&#39;une adaptation nécessaire dans Studio ; une version précise doit être renseignée avant toute validation. Le téléversement facultatif d&#39;un paquet permet de détecter les moteurs de rendu (renderers) ou les actions utilisés ; en l&#39;absence de fichier, cette analyse est effectuée par l&#39;administration. Les fonctionnalités inconnues se voient attribuer le statut « Adaptation Studio requise » et restent exclues du catalogue public jusqu&#39;à leur mise en œuvre et un nouvel examen. La mise à jour de la page web doit être téléversée par l&#39;exploitant.</p><p>À partir de la version Studio <strong>0.1.212</strong>, un symbole rouge <strong><code>mdi:alert</code></strong> signale la sélection via GitHub ainsi que les instructions d&#39;installation pour les paquets de widgets et d&#39;outils. L&#39;utilisateur doit confirmer qu&#39;il accepte les risques liés à l&#39;installation avant de procéder.</p><p>À partir de la version Studio <strong>0.1.213</strong>, les mises à jour de paquets disponibles sont mises en évidence par un cadre vert autour de leur carte. Pour les nouveaux paquets compatibles, seul le bouton <strong>Installer</strong> apparaît en bleu. Une fois l&#39;installation ou la mise à jour effectuée avec succès, ce marquage disparaît.</p><p>Studio détecte les nouvelles versions de paquets publiées lors de l&#39;ouverture des paramètres des paquets ou via la fonction <strong>Mettre à jour le catalogue</strong>, et propose alors l&#39;option <strong>Mettre à jour</strong>. Cette opération nécessite une correspondance entre les identifiants des paquets ; cela s&#39;applique également aux paquets installés précédemment en local ou via GitHub. Les mises à jour sont installées de manière délibérée ; les dépôts GitHub ne font pas l&#39;objet d&#39;une surveillance automatique.</p><p>Vous trouverez des packs de widgets, des packs d&#39;outils et des outils supplémentaires centralisés dans le <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">catalogue de packs UGSo, disponible sur visualstudio.ugso-software.de</a>. Cela inclut des éléments liés à la technique, à la météo/au chauffage, un sélecteur de couleurs (Colorpicker), ainsi que les outils <strong>Widget Test</strong> et <strong>Tools Test</strong> permettant de vérifier l&#39;installation des packs. L&#39;outil <strong>Packer</strong> (pour Windows et Linux) est également disponible dans la section <strong>Outils supplémentaires</strong>. Les descriptions et les instructions sont hébergées sur ce site open source, tandis que les fichiers des packs sont proposés via le sous-domaine dédié au catalogue.</p><p><strong>Un tableau de bord pour Home Assistant qui sort de l&#39;ordinaire.</strong> « Grafik Visual Studio » est une application expérimentale pour Home Assistant, dotée d&#39;un espace d&#39;édition libre et d&#39;un environnement d&#39;exécution (runtime) séparé. Le projet en est à un stade précoce de développement ; son format et son fonctionnement sont susceptibles d&#39;évoluer. Il n&#39;est pas destiné, pour le moment, à être utilisé dans des tableaux de bord en environnement de production.</p><p><a href="/fr/projects/grafik-visual-studio/editor">Éditeur et raccourcis clavier</a> · <a href="/fr/projects/grafik-visual-studio/widgets">Les 74 widgets</a> · <a href="/fr/projects/grafik-visual-studio/svg-line">Ligne SVG</a> · <a href="/fr/projects/grafik-visual-studio/svg-linebox">SVG LineBox avec vidéos</a> · <a href="/fr/projects/grafik-visual-studio/svg-linebox-math">SVG LineBox Math</a> · <a href="/fr/projects/grafik-visual-studio/widget-packages">Interface pour packs de widgets</a> · <a href="/fr/projects/grafik-visual-studio/tool-packages">Interface pour packs d&#39;outils</a> · <a href="/fr/projects/grafik-visual-studio/packer">Outil de création de packs (Packer)</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio" target="_blank" rel="noreferrer">Code source et application Home Assistant</a></p><p><img src="'+t+'" alt="Éditeur de HA Grafik Visual Studio avec palette de widgets et lignes de connexion SVG"></p><p><em>Vue de l&#39;éditeur avec des lignes de connexion tracées. <a href="/images/grafik-visual-studio/editor-zeichnung.png">Ouvrir l&#39;image en pleine résolution</a>.</em></p><h2 id="was-derzeit-moglich-ist" tabindex="-1">Ce qui est actuellement possible <a class="header-anchor" href="#was-derzeit-moglich-ist" aria-label="Permalink to &quot;Ce qui est actuellement possible {#was-derzeit-moglich-ist}&quot;">​</a></h2><p>À partir de la version <strong>0.1.222</strong> du Studio, l&#39;espace de travail s&#39;affiche en gris dans le thème clair, avec des lignes de grille de couleur anthracite. Dans le thème sombre, l&#39;arrière-plan habituel est conservé ; des lignes de grille légèrement plus claires facilitent le repérage. Cet affichage concerne l&#39;éditeur. L&#39;environnement d&#39;exécution (Runtime) continue d&#39;utiliser l&#39;arrière-plan de page enregistré.</p><p>À partir de la version <strong>0.1.221</strong> du Studio, l&#39;interface s&#39;adapte automatiquement au paramètre clair/sombre indiqué par le navigateur. La barre d&#39;outils, les barres latérales, les boîtes de dialogue et les champs de saisie changent d&#39;apparence en temps réel, sans nécessiter de rechargement. Les arrière-plans de page et les couleurs des widgets enregistrés sont conservés ; le changement de thème n&#39;altère aucun paramètre de projet enregistré.</p><p>À partir de la version <strong>0.1.220</strong> du Studio, l&#39;ouverture d&#39;une nouvelle page affiche directement l&#39;onglet <strong>VUE</strong>. On y trouve les sections suivantes : CSS général, Arrière-plan, Police et texte, Options, Navigation, Barre d&#39;application et paramètres responsifs. Ces sections peuvent être développées ou réduites, mais ne comportent pas de cases à cocher d&#39;activation : les valeurs définies pour la page sont conservées lors de l&#39;enregistrement. Les cases à cocher relatives à des options spécifiques, telles que « Standard », demeurent présentes.</p><p>À partir de la version Studio <strong>0.1.218</strong>, les commandes de commutation HA (Home Assistant) ayant échoué s&#39;affichent sous forme de message rouge dans l&#39;interface d&#39;exécution (Runtime), indiquant l&#39;ID de l&#39;entité et la cause de l&#39;erreur. À partir de la version <strong>0.1.219</strong>, un clic sur un commutateur verrouillé permet également d&#39;en afficher la raison, par exemple un état HA manquant ou indisponible. Les widgets commutables permettent de piloter Home Assistant dans l&#39;interface d&#39;exécution ; dans l&#39;éditeur, ils servent à prévisualiser le fonctionnement.</p><p>À partir de la version Studio <strong>0.1.217</strong>, la boîte de dialogue des entités permet d&#39;effectuer des recherches parmi les noms d&#39;affichage, les noms d&#39;entités (personnalisés ou d&#39;origine), les ID d&#39;entités ainsi que les noms des appareils. Il est possible d&#39;utiliser plusieurs termes de recherche répartis entre l&#39;entité et l&#39;appareil : par exemple, la requête <strong>Licht Tv1</strong> permet de trouver une entité nommée « Licht » associée à l&#39;appareil « TV1 ». La recherche ne tient pas compte de la casse (majuscules/minuscules) ; les groupes d&#39;appareils correspondants se développent automatiquement lors de la recherche.</p><ul><li>Dans la fenêtre des fichiers, le champ de recherche parcourt tous les sous-dossiers de <code>/config/www/studio</code>, indépendamment du dossier ouvert. La recherche ignore la casse et porte sur les noms de fichiers ainsi que sur les chemins. Les résultats affichent un aperçu de l’image et le chemin relatif ; les filtres de type de fichier et l’insertion d’images restent disponibles. Un champ de recherche vide affiche de nouveau le dossier ouvert.</li><li>Il est possible de déplacer simultanément plusieurs widgets sélectionnés en faisant glisser l&#39;un d&#39;entre eux, y compris après une opération de copier-coller. Les lignes SVG et les points intermédiaires sélectionnés suivent le mouvement ; les connexions d&#39;ancrage existantes sont préservées. Les widgets verrouillés empêchent le déplacement groupé. Une opération de déplacement peut être annulée dans son intégralité.</li><li>La liste de sélection des widgets reste visible au premier plan, par-dessus tous les autres widgets. À partir de la version <strong>0.1.209</strong>, les widgets cochés sont gérés via les fonctions <strong>Copier</strong> et <strong>Supprimer</strong> situées dans la barre d&#39;outils ; les boutons en double, auparavant présents en bas de la liste, sont supprimés. Une boîte de dialogue de confirmation s&#39;affiche lors de toute suppression.</li><li>Lors de la suppression de widgets, une boîte de dialogue de confirmation s&#39;affiche, indiquant les identifiants (ID) des widgets sélectionnés. Les options « Annuler » ou la touche Échap permettent d&#39;interrompre l&#39;opération ; l&#39;option « Ne plus demander pendant les 5 prochaines minutes » permet de masquer les demandes de confirmation pour toute suppression ultérieure durant les cinq minutes suivantes, dans l&#39;éditeur ouvert. L&#39;action de suppression reste annulable (fonction « Annuler »).</li><li>La sélection de widgets — qu&#39;il s&#39;agisse d&#39;éléments individuels ou de l&#39;ensemble des widgets — est immédiatement répercutée dans la zone de l&#39;éditeur. Pour les nouveaux widgets, les options « Images de signalisation », « Contrôle supplémentaire » et « Points d&#39;ancrage » sont désactivées par défaut, mais peuvent être activées si nécessaire.</li><li>La sélection d&#39;images pour les widgets repose également sur le mécanisme <strong><code>/config/www/studio</code></strong> ; les chemins d&#39;accès aux images repris ou copiés commencent par <strong><code>/local/studio/</code></strong>.</li><li>Possibilité de gérer plusieurs projets ainsi que des pages nommées, chacune disposant de ses propres dimensions, de son propre arrière-plan et de ses propres widgets. L&#39;environnement d&#39;exécution (Runtime) affiche les pages visibles de manière distincte.</li><li>Placez, déplacez, redimensionnez, nommez et organisez les widgets (via l&#39;index Z) sur une surface accessible par défilement. L&#39;éditeur propose des fonctionnalités telles que la sélection multiple, l&#39;alignement, l&#39;ajustement de la taille, le copier-coller, ainsi que les fonctions « annuler » et « rétablir ».</li><li>Utilisez 74 widgets répartis dans les catégories « HA Grafik – Basis », « HA Grafik – Interaktiv », « HA Grafik – Spezial », « HA Grafik – Datenfluss » et « HA Grafik – Gauges ». Cela inclut des éléments HTML, des images, des affichages numériques, des commandes, des tableaux, des calendriers, l&#39;intégration de tableaux de bord, des lignes SVG, des calculs, des convertisseurs et dix types d&#39;instruments de mesure. La palette affiche un aperçu ou une icône selon le type de widget.</li><li>Modifiez les propriétés relatives à la mise en page, au CSS, aux paramètres généraux, à la visibilité et aux points d&#39;ancrage. Le filtre de widgets de l&#39;éditeur utilise le champ « Mot-clé de filtre » (Filterwort) situé dans la section « Général ».</li><li>Utilisez le widget spécial pour tracer des lignes de connexion dotées de points intermédiaires et de points de regroupement (activables explicitement), avec personnalisation des couleurs, des pointes de flèche et des animations. Les lignes qui se croisent ne se connectent pas automatiquement entre elles.</li><li>Sélectionnez des fichiers depuis le dossier <code>/config/www/studio</code> de Home Assistant et importez des fichiers pris en charge. Le navigateur de fichiers crée automatiquement ce répertoire racine à l&#39;ouverture ; si les droits d&#39;écriture sont insuffisants, une notification vous invitera à le créer manuellement. Le navigateur d&#39;entités permet de rechercher des entités ainsi que leurs états actuels, et d&#39;intégrer les identifiants d&#39;entité (Entity IDs) dans les champs des widgets.</li><li>Enregistrez vos modifications automatiquement après un délai configurable (cinq secondes par défaut) ou effectuez une sauvegarde manuelle. Les widgets peuvent être exportés et importés au format JSON.</li><li>L&#39;interface adopte la langue configurée dans Home Assistant : l&#39;allemand si HA est en allemand, l&#39;anglais dans le cas contraire. Dans <strong>Paramètres → Langue</strong>, chaque navigateur peut être configuré sur <strong>Automatique</strong>, <strong>Allemand</strong> ou <strong>Anglais</strong>. Le contenu des projets et des widgets demeure inchangé.</li></ul><h2 id="erganzungen-bis-0-1-158" tabindex="-1">Ajouts jusqu&#39;à 0.1.158 <a class="header-anchor" href="#erganzungen-bis-0-1-158" aria-label="Permalink to &quot;Ajouts jusqu&#39;à 0.1.158 {#erganzungen-bis-0-1-158}&quot;">​</a></h2><p>L&#39;<a href="/fr/projects/grafik-visual-studio/widgets">aperçu des widgets</a> présente désormais, avec des illustrations, les éléments inspirés de VIS2 : listes de valeurs, Bool HTML/Case à cocher/Sélecteur, Tableau, État HTML, Barre, HTML/Navigation, Filtre, Chaîne de caractères (String) et saisie de valeur (Input val). Les paramètres CSS généraux restent actifs pour chaque widget. Les conseils destinés aux utilisateurs effectuant une migration peuvent être désactivés dans Paramètres → Général.</p><p>L&#39;option <strong>Dashboard in widget</strong> (Tableau de bord dans un widget), située dans la section « Spécial », permet d&#39;intégrer un tableau de bord Home Assistant (jusqu&#39;à 800 × 640 pixels). La fonction <strong>View in widget</strong> (Vue dans un widget) reste dédiée aux pages créées dans Studio. La section <a href="/fr/projects/grafik-visual-studio/datenfluss">Flux de données</a> propose des outils de liaison, de conversion et de calcul de valeurs ; <a href="/fr/projects/grafik-visual-studio/svg-linebox-math">LineBox Math</a> offre quatre types de calculs ainsi qu&#39;un affichage personnalisable.</p><h2 id="geplante-erweiterungen" tabindex="-1">Extensions prévues <a class="header-anchor" href="#geplante-erweiterungen" aria-label="Permalink to &quot;Extensions prévues {#geplante-erweiterungen}&quot;">​</a></h2><p>À l&#39;avenir, Grafik Visual Studio ne servira pas uniquement à la création de visualisations, mais aussi à leur distribution et à leur affichage de manière indépendante. Les points suivants constituent des objectifs de développement. Ils ne correspondent pas encore à des fonctionnalités pleinement disponibles ; leur périmètre et leur ordre de réalisation sont susceptibles d&#39;évoluer en fonction des résultats des tests et des retours des utilisateurs. L&#39;ensemble des fonctionnalités actuellement disponibles est présenté dans la section <strong>Ce qui est possible actuellement</strong>.</p><ul><li><strong>Exportation et importation de projets complets :</strong> Sauvegarder, transférer et restaurer des projets — incluant les images nécessaires, les paramètres et les informations sur les paquets — sur une autre installation. Cette fonctionnalité d&#39;exportation de « paquets de projet » viendra compléter l&#39;exportation JSON existante, qui ne concerne que des widgets individuels.</li><li><strong>Environnement d&#39;exécution (Runtime) séparé sur un appareil dédié :</strong> Exécuter des visualisations finalisées indépendamment de l&#39;éditeur, par exemple sur un Raspberry Pi utilisé comme écran mural ou panneau de contrôle. La connexion à Home Assistant sera configurable. La vue « Runtime » existante servira de base ; un paquet « Runtime » autonome, destiné à des appareils distincts, constitue un objectif supplémentaire.</li><li><strong>Application de couplage :</strong> Une application complémentaire est prévue pour faciliter la configuration et l&#39;établissement des connexions entre le Studio, le Runtime et Home Assistant. Le périmètre fonctionnel exact reste à définir.</li><li><strong>Outil de création de paquets (Packer) avancé avec intégration GitHub :</strong> Créer localement des paquets de widgets ou d&#39;outils, avec la possibilité de créer un dépôt GitHub et d&#39;y publier des versions du paquet. La création de paquets en local restera possible sans recours à GitHub. De plus amples informations sur l&#39;outil existant sont disponibles sous <a href="/fr/projects/grafik-visual-studio/packer">Packer pour les paquets</a>.</li><li><strong>Enregistrement direct des paquets depuis le « Packer » :</strong> Soumettre des paquets au <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">Catalogue de la communauté</a> en fournissant les mêmes informations (licence, auteur, politique de confidentialité, compatibilité avec le Studio) que celles requises sur le site web. L&#39;intégration au catalogue public reste soumise à une vérification préalable.</li></ul><h3 id="was-dazu-dokumentiert-werden-soll" tabindex="-1">Éléments devant faire l&#39;objet d&#39;une documentation <a class="header-anchor" href="#was-dazu-dokumentiert-werden-soll" aria-label="Permalink to &quot;Éléments devant faire l&#39;objet d&#39;une documentation {#was-dazu-dokumentiert-werden-soll}&quot;">​</a></h3><ul><li><strong>Transférabilité :</strong> Quelles ressources sont incluses dans une exportation, quels packs d&#39;extension sont requis sur la cible et quelles connexions doivent y être configurées.</li><li><strong>Identifiants :</strong> Gestion des jetons (tokens) Home Assistant et des identifiants GitHub. Une exportation de projet standard ne doit contenir aucune donnée sensible (secrets) en clair.</li><li><strong>Prérequis d&#39;exécution (Runtime) :</strong> Appareils pris en charge, configuration, connexion réseau et comportement en cas de perte de connexion.</li><li><strong>Maintenance des paquets et compatibilité :</strong> Gestion des versions, mises à jour et interaction entre le Studio, le Runtime et les packs d&#39;extension.</li><li><strong>Contribuer :</strong> Recherche de testeurs et de développeurs ; canaux pour signaler des bugs ou faire des suggestions. Les problèmes peuvent être rapportés via les <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">GitHub Issues</a>. Si vous avez découvert le projet via un message sur le forum, vous pouvez également contacter l&#39;auteur par la messagerie privée du forum ; une expérience avec ioBroker VIS/VIS2 est un atout.</li></ul><h2 id="vorgemerkt-kalender-json-integration" tabindex="-1">En projet : Intégration JSON pour calendrier <a class="header-anchor" href="#vorgemerkt-kalender-json-integration" aria-label="Permalink to &quot;En projet : Intégration JSON pour calendrier {#vorgemerkt-kalender-json-integration}&quot;">​</a></h2><p>Une intégration dédiée pour Home Assistant est prévue ; elle fournira les calendriers HA sous forme de listes d&#39;événements au format JSON, exploitables par des widgets de calendrier ou d&#39;autres composants. Le nombre d&#39;événements correspondra à l&#39;état du capteur, tandis que la liste complète sera disponible dans l&#39;attribut <code>events</code>. La période couverte et la fréquence de mise à jour seront configurables. Une connexion directe (<code>calendar.*</code>) au calendrier existe déjà, mais cette intégration réutilisable reste à implémenter.</p><h2 id="grenzen-des-aktuellen-stands" tabindex="-1">Limites de l&#39;état actuel <a class="header-anchor" href="#grenzen-des-aktuellen-stands" aria-label="Permalink to &quot;Limites de l&#39;état actuel {#grenzen-des-aktuellen-stands}&quot;">​</a></h2><p>Dans le Runtime, les éléments de type Sensor, String, Red Number, Bar, Gauge et Bool HTML interrogent l&#39;entité Home Assistant associée toutes les cinq secondes ; les règles de visibilité s&#39;appuient également sur ces états. Un widget de type « interrupteur » (switch) permet de commander <code>switch</code>, <code>light</code> et <code>input_boolean</code> via les services HA, et affiche ensuite l&#39;état confirmé par HA. Les autres widgets de données et de contrôle utilisent encore des valeurs de test locales. La sélection d&#39;un « Entity ID » (identifiant d&#39;entité) ne correspond pas encore à une connexion en temps réel. L&#39;option « Uniquement pour les groupes » (dans les paramètres de visibilité) ainsi que le comportement de <code>multi-views</code> ne sont pas encore totalement implémentés. Le filtre de l&#39;éditeur ne s&#39;applique qu&#39;à la vue de l&#39;éditeur.</p><p>L&#39;application dispose d&#39;une entrée standard « Home Assistant Ingress ». L&#39;utilisation d&#39;entrées distinctes dans la barre latérale pour l&#39;éditeur et l&#39;environnement d&#39;exécution (runtime) nécessite l&#39;intégration expérimentale issue de <code>custom_components/ha_grafik_visual_studio</code> ; celle-ci requiert Home Assistant OS ou une installation de type « Supervised » (avec Supervisor). Le fichier README du dépôt (<a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/README.md" target="_blank" rel="noreferrer">https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/README.md</a>) détaille les étapes d&#39;installation.</p><p>L&#39;interface utilisateur s&#39;inspire de VIS2. « Grafik Visual Studio » est une implémentation indépendante ; le code et les widgets de VIS2 ne sont pas inclus.</p>',43)])])}const v=s(r,[["render",o]]);export{f as __pageData,v as default};
